CREATE TABLE logistica_spedizioni (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identificativo_ordine TEXT NOT NULL,
    finestra_di_evasione DATE NOT NULL,
    stato_consegna TEXT NOT NULL,
    peso_kg NUMERIC(10, 2) NOT NULL CHECK (peso_kg > 0),
    destinazione_codice_postale TEXT NOT NULL,
    CONSTRAINT check_stato_consegna CHECK (stato_consegna IN ('IN_TRANSITO', 'CONSEGNATO', 'IN_ATTESA', 'FALLITO'))
);

CREATE INDEX idx_spedizioni_temporali ON logistica_spedizioni (finestra_di_evasione, stato_consegna);
